// AUTO-GENERATED by Mosaic. Edits will be overwritten on next emit.
//
// mosaic_platform_effects_core.dart -- the operating-system capabilities
// Mosaic provides on Flutter, shared by every generated app (UI87 §7, §7.7).
//
// Generated by mosaic-app-bindings; do not edit in a generated project. An app
// that needs different behaviour for a standard kind claims that kind in its
// own `[host_effects]` handler instead (UI87 §7.2).
//
// What it answers
// ---------------
//
//   files.open  { accept: [MIME...] }
//               -> ok { name, mimeType, bytes (base64) } | cancelled {} | failed { message }
//   files.save  { suggestedName, accept: [MIME...], bytes (base64) }
//               -> ok { name } | cancelled {} | failed { message }
//
// These are UI59's and UI87's contracts, answered exactly as the Compose,
// SwiftUI, Qt and XAML libraries answer them: the same limits, MIME table,
// plain-name rule, executable list and failure messages. A name is returned,
// never a path: a path would tell the app (and anything it logs) where the
// person keeps files.
//
// Routing
// -------
//
// The generated main.dart installs the app's own handler first, then this,
// which wraps it. Each effect is routed by kind:
//
//   kind the app claims ........ the app's handler
//   files.open / files.save .... this library
//   anything else .............. the app's handler if it claimed nothing
//                                (the original meaning), otherwise nobody --
//                                and the host fails an unanswered Await
//                                rather than leaving it pending.
//
// Threading
// ---------
//
// A Dart isolate is single-threaded, so there is no lock to hold and no
// thread to marshal an answer onto: the host calls the handler inside its
// settle, and an answer given later arrives on a later turn of the same
// isolate's event loop. What remains is ordering and cost:
//
//   1. The handler DEFERS each standard effect before anything asynchronous
//      starts. A handler cannot wait for a dialog -- it is a synchronous
//      callback -- and an effect that is neither answered nor deferred by
//      the time it returns is swept and failed by the host.
//   2. The dialog is started from a microtask, after the settle has returned,
//      as XAML starts its picker from the DispatcherQueue: nothing the
//      dialog does can reach the host half-way through a settle.
//   3. The file itself is read (up to 50 MiB, then base64-encoded) or written
//      and flushed in a short-lived background isolate (`Isolate.run`), so a
//      large file never stalls the frame the UI isolate is drawing. The
//      outcome comes back to the UI isolate, which gives the answer.
//
// Nothing may escape that work. Once deferred, an effect is out of the host's
// fail sweep, so an exception that ended the future would leave the Await
// pending for the life of the process -- and the runtime refuses to snapshot
// while anything is pending. Every path ends in `completeEffect`, with
// `failed` when nothing better is known.
//
// The answer goes to the runtime that asked. The router holds the host
// INSTANCE it was installed on (never a static facade), and the generated
// shell's retried start disposes that host and loads a new one with its own
// router. A late answer therefore meets the disposed host, whose
// `completeEffect` throws, and is dropped; it can never settle the new
// runtime's effect that happens to reuse the id (the XAML library had to add
// `EffectScope` to get the same property, UI87 §7.6).
//
// What compiles where
// -------------------
//
// This file is plain Dart (dart:io, dart:ffi, package:ffi), so the headless
// conformance harness runs it on the Dart VM with a fake host and fake
// dialogs. The dialogs themselves need the Flutter engine: they live in
// `mosaic_platform_effects.dart`, which re-exports this file and is the one
// the generated main.dart imports. Dart has no conditional compilation, so
// the split is two files rather than XAML's one fenced file.

import 'dart:async';
import 'dart:convert';
import 'dart:ffi';
import 'dart:io';
import 'dart:isolate';
import 'dart:math';
import 'dart:typed_data';

import 'package:ffi/ffi.dart';

import 'mosaic_host.dart';

/// The shape of a host's effect handler: `(id, kind, payload, delivery)`.
typedef MosaicEffectHandler =
    void Function(int id, String kind, Object? payload, String delivery);

/// The effect kinds this library answers unless an app claims them.
const Set<String> mosaicStandardEffectKinds = <String>{
  'files.open',
  'files.save',
};

/// The largest file `files.open` reads (UI59 parity with every other host).
const int mosaicMaxOpenBytes = 50 * 1024 * 1024;

/// The largest payload `files.save` writes (UI87 §3.1).
const int mosaicMaxSaveBytes = 16 * 1024 * 1024;

/// Whether this platform has the file dialogs this library drives.
///
/// `file_selector` shows native dialogs on Linux, macOS and Windows. Android
/// and iOS have pickers only through a phone build's document plugin
/// (UI89 §7.11), which the router is given as `phoneDocuments`; without it
/// each request fails with a message rather than pretending the person
/// cancelled.
bool get mosaicPlatformHasFileDialogs =>
    Platform.isLinux || Platform.isMacOS || Platform.isWindows;

/// The two dialogs, behind an interface so a test can answer them without a
/// display. Each returns the chosen file's full path, or null when the person
/// cancelled. Asynchronous because every Flutter plugin call is.
abstract interface class MosaicFileDialogs {
  Future<String?> chooseFileToOpen(List<String> extensions);

  Future<String?> chooseFileToSave(
    String suggestedName,
    List<String> extensions,
  );
}

/// Asks the person whether to replace the existing file called [fileName].
/// True replaces it; false (or a dismissed question) keeps it, and the save is
/// a cancel.
typedef MosaicReplaceQuestion = Future<bool> Function(String fileName);

/// The save dialog's choice, after asking before replacing an existing file
/// where the dialog itself did not (UI87 §7.7).
///
/// NSSavePanel and the Windows dialog ask before a person saves over a file.
/// GTK's chooser can, but `file_selector_linux` never turns that on, so on
/// Linux the library asks itself:
///
///     dialog asked?   something at the path?   result
///     yes             (not checked)            the choice
///     no              no                       the choice
///     no              yes                      [ask]: the choice, or null
///     --              (cancelled: null)        null
///
/// Anything at the path counts -- a link, even a dangling one, is a name the
/// save would replace. The save itself still replaces atomically and refuses
/// what it must; this only adds the question a person expects.
Future<String?> mosaicConfirmReplacing(
  String? chosen, {
  required bool dialogAsked,
  required MosaicReplaceQuestion ask,
}) async {
  if (chosen == null || dialogAsked) return chosen;
  final existing = FileSystemEntity.typeSync(chosen, followLinks: false);
  if (existing == FileSystemEntityType.notFound) return chosen;
  return await ask(_mosaicBaseName(chosen)) ? chosen : null;
}

/// What the router needs from a host: the handler slot, deferral and the
/// answer. [MosaicHostEffects] adapts the generated [MosaicHost]; a test
/// supplies a fake, so routing and deferral run without a Rust runtime.
abstract interface class MosaicPlatformEffectHost {
  MosaicEffectHandler? get effectHandler;

  set effectHandler(MosaicEffectHandler? handler);

  /// Take ownership of an awaited effect; false when it is not awaited.
  bool deferEffect(int id);

  /// Answer an effect. Throws when the host can no longer take the answer
  /// (disposed, or no runtime at all); the router drops it then.
  void completeEffect(int id, Map<String, Object?> result);
}

/// The generated [MosaicHost], seen through [MosaicPlatformEffectHost].
///
/// Bound to the ONE host it wraps, which owns one runtime: after
/// `dispose()` that runtime's `completeEffect` throws, so an answer that
/// arrives after a retried start is refused rather than delivered to the
/// runtime that replaced it.
final class MosaicHostEffects implements MosaicPlatformEffectHost {
  MosaicHostEffects(this.host);

  final MosaicHost host;

  @override
  MosaicEffectHandler? get effectHandler => host.effectHandler;

  @override
  set effectHandler(MosaicEffectHandler? handler) {
    host.effectHandler = handler;
  }

  @override
  bool deferEffect(int id) => host.deferEffect(id);

  @override
  void completeEffect(int id, Map<String, Object?> result) {
    // `MosaicHost.completeEffect` returns null only when there is no runtime
    // behind the host: nothing can take the answer.
    if (host.completeEffect(id, result) == null) {
      throw StateError('this Mosaic host has no runtime to answer');
    }
  }
}

// ── The contract's tables ─────────────────────────────────────────────────
//
// The MIME types an app names, and the extensions a dialog filters on -- the
// same table, in the same order, as the Compose library (a Rust test pins the
// two together). A type this table does not know is dropped rather than
// failing the request (UI59 §3). Extensions are bare, with no leading dot:
// `file_selector` turns `json` into the Linux and Windows filter `*.json`,
// and a leading dot would make it `*..json`.
const List<(String, List<String>)> _mosaicMimeExtensions =
    <(String, List<String>)>[
      ('application/json', <String>['json']),
      ('text/plain', <String>['txt']),
      ('text/markdown', <String>['md', 'markdown']),
      ('text/csv', <String>['csv']),
      ('application/pdf', <String>['pdf']),
      ('application/zip', <String>['zip']),
      ('image/jpeg', <String>['jpg', 'jpeg']),
      ('image/png', <String>['png']),
      ('image/webp', <String>['webp']),
      ('image/gif', <String>['gif']),
      ('image/bmp', <String>['bmp']),
      ('image/tiff', <String>['tif', 'tiff']),
      ('image/svg+xml', <String>['svg']),
    ];

/// Extensions that run when the file is opened, on some platform: when an app
/// names no type (`accept` empty) a save may not end in one of these, so a
/// `files.save` cannot drop a launcher next to the person's documents. When
/// the app does name types, the name must already end in one of theirs. One
/// list on every host (a Rust test pins it to the Compose library's).
const Set<String> mosaicExecutableExtensions = <String>{
  // macOS: Terminal scripts, Finder location files and installers open
  // with no prompt, or install.
  'command', 'terminal', 'tool', 'webloc', 'inetloc', 'fileloc', 'afploc', 'ftploc',
  'mailloc', 'newsloc', 'atloc', 'app', 'pkg', 'mpkg', 'dmg', 'mobileconfig', 'scpt',
  'applescript', 'workflow',
  // Windows: run, install, or leak credentials when merely browsed.
  'exe', 'com', 'bat', 'cmd', 'scr', 'pif', 'msi', 'msp', 'msc', 'lnk', 'url', 'hta',
  'cpl', 'chm', 'inf', 'vbs', 'vbe', 'js', 'jse', 'wsf', 'wsh', 'ws', 'wsc', 'sct',
  'ps1', 'psm1', 'reg', 'jar', 'jnlp', 'gadget', 'xll', 'appref-ms', 'application',
  'settingcontent-ms', 'appx', 'msix', 'appinstaller', 'diagcab', 'scf',
  'library-ms', 'searchconnector-ms', 'iso', 'img', 'vhd', 'vhdx',
  // Linux desktops.
  'desktop', 'sh', 'run', 'appimage', 'deb', 'rpm', 'flatpakref',
  // Documents that run code when opened: web pages and SVG (their script
  // runs from the local file), saved web archives and shortcuts, and Office
  // files that carry macros.
  'html', 'htm', 'xhtml', 'xht', 'shtml', 'svg', 'svgz', 'mht', 'mhtml', 'website',
  'docm', 'dotm', 'xlsm', 'xltm', 'xlam', 'pptm', 'potm', 'ppam', 'ppsm', 'sldm',
  'xlsb', 'xla',
  // Scripts an installed interpreter runs on a double-click.
  'py', 'pyw', 'pyz', 'pyzw', 'pyc',
  // Shortcuts that fetch or connect: Excel web queries, SYLK, Remote Desktop.
  'iqy', 'slk', 'rdp',
};

// ── Outcomes ──────────────────────────────────────────────────────────────
//
// Plain maps, which the host encodes as JSON:
// `{"ok": {...}}`, `{"cancelled": {}}`, `{"failed": {"message": ...}}`.

Map<String, Object?> _mosaicOk(Map<String, Object?> value) =>
    <String, Object?>{'ok': value};

Map<String, Object?> _mosaicCancelled() => <String, Object?>{
  'cancelled': <String, Object?>{},
};

/// The `failed` outcome with [message], which the app sees.
Map<String, Object?> mosaicFailed(String message) => <String, Object?>{
  'failed': <String, Object?>{'message': message},
};

// ── Reading the payload ───────────────────────────────────────────────────
//
// The payload is whatever the app sent. Anything that is not the expected
// shape reads as absent, never as an exception: `files.open` with no `accept`
// is "any file", and `files.save` with no `suggestedName` fails the
// plain-name rule like an empty one.

String? _mosaicText(Object? payload, String key) {
  final value = payload is Map ? payload[key] : null;
  return value is String ? value : null;
}

/// The extensions for the accepted MIME types, deduplicated, in order.
List<String> mosaicExtensionsFor(Object? payload) {
  final accept = payload is Map ? payload['accept'] : null;
  final extensions = <String>[];
  if (accept is! List) return extensions;
  for (final mime in accept) {
    if (mime is! String) continue;
    for (final (rowMime, rowExtensions) in _mosaicMimeExtensions) {
      if (rowMime != mime) continue;
      for (final extension in rowExtensions) {
        if (!extensions.contains(extension)) extensions.add(extension);
      }
    }
  }
  return extensions;
}

/// The text after the last `.` of a file name, or empty.
String _mosaicExtensionOf(String name) {
  final dot = name.lastIndexOf('.');
  return dot < 0 ? '' : name.substring(dot + 1);
}

String _mosaicMimeTypeFor(String name) {
  final extension = _mosaicExtensionOf(name).toLowerCase();
  for (final (mime, extensions) in _mosaicMimeExtensions) {
    if (extensions.contains(extension)) return mime;
  }
  return 'application/octet-stream';
}

/// The last component of [path]: the name the app is told, never the path.
String _mosaicBaseName(String path) {
  final separators = Platform.isWindows ? RegExp(r'[\\/]') : RegExp('/');
  return path.split(separators).last;
}

/// A deep copy of a JSON-shaped value: maps and lists are copied, strings,
/// numbers, booleans and null are immutable and shared.
///
/// The payload belongs to the host's parsed update, which the host is free to
/// keep, change or drop once the handler returns; the dialog answers long
/// after that. XAML's harness proved the request fails without its copy there
/// (UI87 §7.6), so the same discipline is kept here.
Object? _mosaicCopyJson(Object? value) {
  if (value is Map) {
    return <Object?, Object?>{
      for (final entry in value.entries)
        entry.key: _mosaicCopyJson(entry.value),
    };
  }
  if (value is List) {
    return <Object?>[for (final item in value) _mosaicCopyJson(item)];
  }
  return value;
}

// ── The plain-name rule ───────────────────────────────────────────────────
//
// Dart has no Unicode general-category API, but its regular expressions do,
// in Unicode mode: `\p{Cf}` is "format", `\p{Cn}` "unassigned", and so on.
// The tables are the Dart VM's own, as the Compose rule's are the JDK's.

/// Control, format, line and paragraph separators, surrogates, unassigned and
/// private-use code points: none belongs in a file name.
final RegExp _mosaicRefusedCharacter = RegExp(
  r'^[\p{Cc}\p{Cf}\p{Zl}\p{Zp}\p{Cs}\p{Cn}\p{Co}]$',
  unicode: true,
);

/// Unicode's space, line and paragraph separators (no-break spaces included).
final RegExp _mosaicSeparatorCharacter = RegExp(
  r'^[\p{Zs}\p{Zl}\p{Zp}]$',
  unicode: true,
);

/// A suggested name is a plain file name (UI87 §3.1), so an app cannot steer
/// the dialog, or disguise what it is saving -- the same rule as the Compose
/// library:
///
/// - no directory separators, and not `.` or `..` -- no other directory;
/// - no leading `.` -- a hidden dot-file such as `.zshrc` is configuration a
///   shell or tool runs, not a document;
/// - no `:` -- on Windows `D:x` names another drive, and `x:y` an alternate
///   data stream;
/// - no control, format, line- or paragraph-separator characters -- a
///   right-to-left override can make `invoice<RLO>fdp.exe` read as a PDF in
///   the dialog, and a separator breaks the name across lines;
/// - no lone surrogate, unassigned or private-use code point -- they mean
///   different things to different runtimes' Unicode tables;
/// - no leading or trailing whitespace of any kind (a no-break space
///   included), no run of two or more, and no trailing dot, which Windows
///   silently strips -- `report.pdf` padded out and ending `.command` hides
///   its real extension. Blank-rendering characters (Hangul fillers, BRAILLE
///   PATTERN BLANK) count as whitespace, and invisible (default-ignorable)
///   characters are dropped before these padding and dot rules;
/// - at most 255 UTF-16 units.
///
/// Checked by code point, so a format character outside the BMP (the tag
/// characters, U+E0000..) is caught as well as one inside it.
bool mosaicIsPlainFileName(String name) {
  if (name.isEmpty || name.length > 255 || name == '.' || name == '..') {
    return false;
  }
  final points = _mosaicCodePoints(name);
  if (points == null) return false;
  for (final point in points) {
    if (point == 0x2F || point == 0x5C || point == 0x3A) return false; // / \ :
    if (_mosaicRefusedCharacter.hasMatch(String.fromCharCode(point))) {
      return false;
    }
  }
  // The padding and dot rules look at what is visible: invisible characters
  // cannot split a run of spaces or hide a leading or trailing dot.
  final visible = <int>[
    for (final point in points)
      if (!_mosaicIsInvisible(point)) point,
  ];
  if (visible.isEmpty) return false;
  if (visible.first == 0x2E || visible.last == 0x2E) return false; // .
  if (_mosaicIsSpace(visible.first) || _mosaicIsSpace(visible.last)) {
    return false;
  }
  for (var index = 1; index < visible.length; index += 1) {
    if (_mosaicIsSpace(visible[index - 1]) && _mosaicIsSpace(visible[index])) {
      return false;
    }
  }
  return !mosaicIsReservedDeviceName(name);
}

/// Windows device names: `CON`, `NUL.txt` or `com1.json` is the console,
/// the null device or a serial port there, never a file. Refused on every
/// host, so a name saves the same everywhere. Compared on the part before
/// the first dot, trailing spaces removed, ASCII letters folded to upper case (only those: a host's own upper-casing differs on `ı`).
const Set<String> mosaicReservedDeviceNames = <String>{
  'CON', 'PRN', 'AUX', 'NUL', 'CONIN\$', 'CONOUT\$', 'COM0', 'COM1',
  'COM2', 'COM3', 'COM4', 'COM5', 'COM6', 'COM7', 'COM8', 'COM9',
  'COM¹', 'COM²', 'COM³', 'LPT0', 'LPT1', 'LPT2', 'LPT3', 'LPT4',
  'LPT5', 'LPT6', 'LPT7', 'LPT8', 'LPT9', 'LPT¹', 'LPT²', 'LPT³',
};

/// True when [name] is a Windows device name (see
/// [mosaicReservedDeviceNames]).
bool mosaicIsReservedDeviceName(String name) {
  final dot = name.indexOf('.');
  final stem = (dot < 0 ? name : name.substring(0, dot)).replaceFirst(
    RegExp(r' +$'),
    '',
  );
  // ASCII letters only: every host's own upper-casing differs on some
  // character (.NET's leaves `ı` alone, the others make it `I`).
  final folded = String.fromCharCodes(
    stem.codeUnits.map((unit) => unit >= 0x61 && unit <= 0x7A ? unit - 0x20 : unit),
  );
  return mosaicReservedDeviceNames.contains(folded);
}

/// The code points of [name], or null when it holds a lone surrogate (which
/// cannot be a file name). Walked by hand over UTF-16 units: `String.runes`
/// would hand a lone surrogate back as if it were a code point, and a JSON
/// payload can carry one (`"\ud800"`).
List<int>? _mosaicCodePoints(String name) {
  final points = <int>[];
  for (var index = 0; index < name.length; index += 1) {
    final unit = name.codeUnitAt(index);
    if (unit >= 0xD800 && unit <= 0xDBFF) {
      if (index + 1 >= name.length) return null;
      final next = name.codeUnitAt(index + 1);
      if (next < 0xDC00 || next > 0xDFFF) return null;
      points.add(0x10000 + ((unit - 0xD800) << 10) + (next - 0xDC00));
      index += 1;
    } else if (unit >= 0xDC00 && unit <= 0xDFFF) {
      return null;
    } else {
      points.add(unit);
    }
  }
  return points;
}

/// Characters that are not whitespace to Unicode but render as a wide blank,
/// so they pad a name just as well: the Hangul fillers and BRAILLE PATTERN
/// BLANK. Whitespace for the padding rules.
bool _mosaicIsBlank(int point) =>
    point == 0x115F ||
    point == 0x1160 ||
    point == 0x2800 ||
    point == 0x3164 ||
    point == 0xFFA0;

/// Whitespace as the Compose library means it: Java's
/// `isWhitespace || isSpaceChar` -- every space, line and paragraph
/// separator (no-break spaces included), the ASCII whitespace controls --
/// plus the blanks above.
bool _mosaicIsSpace(int point) =>
    (point >= 0x09 && point <= 0x0D) ||
    (point >= 0x1C && point <= 0x1F) ||
    _mosaicIsBlank(point) ||
    _mosaicSeparatorCharacter.hasMatch(String.fromCharCode(point));

/// Unicode's Default_Ignorable_Code_Point, minus the blanks above: variation
/// selectors, COMBINING GRAPHEME JOINER and the like -- the same ranges as the
/// Compose library. Dropped before the padding and dot rules, so
/// `<space><VS1><space>` is still a run while an emoji's own selector
/// (`❤️ list.txt`) is fine.
bool _mosaicIsInvisible(int point) =>
    !_mosaicIsBlank(point) &&
    (point == 0x00AD ||
        point == 0x034F ||
        point == 0x061C ||
        (point >= 0x115F && point <= 0x1160) ||
        (point >= 0x17B4 && point <= 0x17B5) ||
        (point >= 0x180B && point <= 0x180F) ||
        (point >= 0x200B && point <= 0x200F) ||
        (point >= 0x202A && point <= 0x202E) ||
        (point >= 0x2060 && point <= 0x206F) ||
        point == 0x3164 ||
        (point >= 0xFE00 && point <= 0xFE0F) ||
        point == 0xFEFF ||
        point == 0xFFA0 ||
        (point >= 0xFFF0 && point <= 0xFFF8) ||
        (point >= 0x1BCA0 && point <= 0x1BCA3) ||
        (point >= 0x1D173 && point <= 0x1D17A) ||
        (point >= 0xE0000 && point <= 0xE0FFF));

/// True when [name] ends in an extension from [mosaicExecutableExtensions].
bool mosaicHasExecutableExtension(String name) {
  // A non-ASCII extension counts as one: a lookalike letter (Cyrillic `е` in
  // `ехе`) or a combining mark after `.exe` makes an extension no list can
  // name but a reader takes for an executable one.
  if (name.contains('.') &&
      _mosaicExtensionOf(name).codeUnits.any((unit) => unit > 0x7F)) {
    return true;
  }
  // Folded through upper case first: `ſ` (LONG S) lowercases to itself but
  // is `S` to a case-insensitive file system.
  return name.contains('.') &&
      mosaicExecutableExtensions.contains(
        _mosaicExtensionOf(name).toUpperCase().toLowerCase(),
      );
}

// ── files.open ────────────────────────────────────────────────────────────

/// `files.open`: the outcome map, never an exception from the file. (A
/// dialog that throws is the router's to answer, as on every other host.)
Future<Map<String, Object?>> mosaicRunFilesOpen(
  Object? payload,
  MosaicFileDialogs dialogs,
) async {
  final chosen = await dialogs.chooseFileToOpen(mosaicExtensionsFor(payload));
  if (chosen == null) return _mosaicCancelled();
  // Up to 50 MiB read and base64-encoded: in a background isolate, not the
  // UI isolate that is drawing frames.
  return _mosaicReadInBackground(chosen);
}

/// [_mosaicReadOpened] in a short-lived isolate.
///
/// A top-level function whose closure captures only [path]: `Isolate.run`
/// copies what its closure captures into the new isolate, and a closure made
/// inside a method that touched `this` could capture the router -- and with
/// it a host holding native pointers, which cannot be sent. The result (the
/// base64 text) comes back without a copy (`Isolate.exit`).
Future<Map<String, Object?>> _mosaicReadInBackground(String path) =>
    Isolate.run(() => _mosaicReadOpened(path));

/// The `files.open` outcome for a chosen path: read, typed, encoded.
///
/// Read at most [mosaicMaxOpenBytes], bounded while reading, not by checking
/// the length first: a file can grow between a check and a read, which is
/// the TOCTOU the first XAML handler's review found (#15218).
///
/// A directory or a missing path is refused up front, following a link the
/// person chose (a device is refused here too: dart:io types it as not
/// found, so it is never opened). On Linux and macOS the file is then opened
/// ONCE, as the Qt and SwiftUI libraries open it
/// ([mosaicReadThroughDescriptor]); elsewhere (Windows,
/// which has no FIFOs a file dialog can return) it is read through dart:io.
Map<String, Object?> _mosaicReadOpened(String path) {
  if (FileSystemEntity.typeSync(path) != FileSystemEntityType.file) {
    return mosaicFailed('that is not a regular file');
  }
  final throughDescriptor = mosaicReadThroughDescriptor(path);
  if (throughDescriptor != null) return throughDescriptor;
  RandomAccessFile? handle;
  try {
    handle = File(path).openSync();
    final builder = BytesBuilder(copy: false);
    while (true) {
      final chunk = handle.readSync(64 * 1024);
      if (chunk.isEmpty) break;
      if (builder.length + chunk.length > mosaicMaxOpenBytes) {
        return _mosaicTooLargeToOpen();
      }
      builder.add(chunk);
    }
    return _mosaicOpened(path, builder.takeBytes());
  } on Object {
    // Not the exception's own text: it can carry the full local path, and a
    // failure message is data the app sees.
    return _mosaicUnreadable();
  } finally {
    try {
      handle?.closeSync();
    } on Object {
      // Closing a read-only handle has nothing left to lose.
    }
  }
}

Map<String, Object?> _mosaicUnreadable() =>
    mosaicFailed("couldn't read the selected file");

Map<String, Object?> _mosaicTooLargeToOpen() =>
    mosaicFailed('the selected file is larger than $mosaicMaxOpenBytes bytes');

/// The `ok` outcome: the name the person chose (never the path), its type
/// from the extension, and the bytes as base64.
Map<String, Object?> _mosaicOpened(String path, Uint8List bytes) {
  final name = _mosaicBaseName(path);
  return _mosaicOk(<String, Object?>{
    'name': name,
    'mimeType': _mosaicMimeTypeFor(name),
    'bytes': base64Encode(bytes),
  });
}

/// The POSIX read: one descriptor, typed and read through itself.
///
///   1. The chosen path is resolved (`realpath`), so a link the person chose
///      is followed once, here, on purpose.
///   2. `open(O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC)`: `O_NOFOLLOW`
///      refuses a link swapped in after that, and `O_NONBLOCK` makes the open
///      -- and any read -- return at once on a FIFO swapped in, where a
///      blocking open would wait for a writer forever and hold `_busy`.
///   3. The type is `fstat` on that descriptor, never a second lookup: only a
///      regular file is read. Where the type cannot be had -- no `statx` (a
///      glibc older than 2.28), or a sandbox that refuses it -- the read
///      fails closed with the generic "couldn't read" message rather than
///      read an untyped descriptor.
///   4. It is read through the same descriptor with `read(2)`.
///
/// The buffer is allocated before the open, so nothing between the open and
/// the `finally` that closes the descriptor can throw.
///
/// Null where there is no descriptor to read through (Windows, or a POSIX ABI
/// without a flag table). Public so the conformance harness can hand it a
/// FIFO and a device directly -- what a swap between the path check and the
/// open would hand it -- which the path check would otherwise refuse first.
Map<String, Object?>? mosaicReadThroughDescriptor(String path) {
  if (Platform.isWindows) return null;
  final posix = _MosaicPosix.load();
  if (posix == null) return null;
  final String resolved;
  try {
    resolved = File(path).resolveSymbolicLinksSync();
  } on Object {
    return _mosaicUnreadable();
  }
  const chunk = 64 * 1024;
  final Pointer<Uint8> buffer;
  try {
    buffer = malloc<Uint8>(chunk);
  } on Object {
    return _mosaicUnreadable();
  }
  final flags = posix.flags;
  final descriptor = posix.open(
    resolved,
    MosaicOpenFlags.readOnly |
        flags.nonBlocking |
        flags.noFollow |
        flags.closeOnExec,
    0,
  );
  if (descriptor < 0) {
    malloc.free(buffer);
    return _mosaicUnreadable();
  }
  try {
    final status = posix.statusOfDescriptor(descriptor);
    // Fail closed: an untyped descriptor is never read.
    if (status == null) return _mosaicUnreadable();
    if (!mosaicIsRegularMode(status.mode)) {
      return mosaicFailed('that is not a regular file');
    }
    final builder = BytesBuilder(copy: true);
    while (true) {
      final count = posix.read(descriptor, buffer, chunk);
      if (count < 0) return _mosaicUnreadable();
      if (count == 0) break;
      if (builder.length + count > mosaicMaxOpenBytes) {
        return _mosaicTooLargeToOpen();
      }
      builder.add(buffer.asTypedList(count));
    }
    return _mosaicOpened(path, builder.takeBytes());
  } on Object {
    return _mosaicUnreadable();
  } finally {
    malloc.free(buffer);
    posix.close(descriptor);
  }
}

// ── files.save ────────────────────────────────────────────────────────────

/// True when every character is in the base64 alphabet or is padding.
///
/// Checked before decoding because Dart's decoder also accepts the URL-safe
/// alphabet (`-`, `_`) and percent-encoded padding (`%3D`), which the Compose
/// and SwiftUI decoders refuse; the same payload should not save on one host
/// and fail on another.
bool _mosaicIsBase64Alphabet(String encoded) {
  for (final unit in encoded.codeUnits) {
    final ok =
        (unit >= 0x41 && unit <= 0x5A) || // A-Z
        (unit >= 0x61 && unit <= 0x7A) || // a-z
        (unit >= 0x30 && unit <= 0x39) || // 0-9
        unit == 0x2B || // +
        unit == 0x2F || // /
        unit == 0x3D; // =
    if (!ok) return false;
  }
  return true;
}

/// A `files.save` request that passed every check: the name, the decoded
/// bytes and the accepted extensions.
typedef _MosaicSaveRequest = ({
  String name,
  Uint8List bytes,
  List<String> extensions,
});

/// The result of checking a `files.save` request: one of the two below.
sealed class _MosaicSaveCheck {}

final class _MosaicSaveChecked extends _MosaicSaveCheck {
  _MosaicSaveChecked(this.request);

  final _MosaicSaveRequest request;
}

final class _MosaicSaveRefused extends _MosaicSaveCheck {
  _MosaicSaveRefused(this.outcome);

  final Map<String, Object?> outcome;
}

/// `files.save`: the outcome map, never an exception from the file.
Future<Map<String, Object?>> mosaicRunFilesSave(
  Object? payload,
  MosaicFileDialogs dialogs,
) async {
  final checked = _mosaicCheckSaveRequest(payload);
  if (checked case _MosaicSaveRefused(:final outcome)) return outcome;
  final (:name, :bytes, :extensions) = (checked as _MosaicSaveChecked).request;
  final target = await dialogs.chooseFileToSave(name, extensions);
  if (target == null) return _mosaicCancelled();
  // Up to 16 MiB written and flushed to disk: in a background isolate, as the
  // read in files.open is. mosaicWriteReplacing never throws.
  return _mosaicWriteInBackground(target, bytes);
}

/// Every check a `files.save` request meets before any dialog or picker is
/// shown, on desktop and phone alike.
_MosaicSaveCheck _mosaicCheckSaveRequest(Object? payload) {
  _MosaicSaveRefused refused(String message) =>
      _MosaicSaveRefused(mosaicFailed(message));
  final suggestedName = _mosaicText(payload, 'suggestedName') ?? '';
  if (!mosaicIsPlainFileName(suggestedName)) {
    return refused('suggestedName must be a plain file name');
  }
  final encoded = _mosaicText(payload, 'bytes');
  if (encoded == null) return refused('bytes must be base64 text');
  // Checked on the encoded length before decoding, so an oversized payload is
  // refused without allocating its decoded copy (4 base64 chars = 3 bytes).
  if (encoded.length > (mosaicMaxSaveBytes ~/ 3 + 1) * 4) {
    return refused('the file is larger than $mosaicMaxSaveBytes bytes');
  }
  final Uint8List bytes;
  try {
    if (!_mosaicIsBase64Alphabet(encoded)) {
      return refused('bytes must be base64 text');
    }
    bytes = base64Decode(encoded);
  } on FormatException {
    return refused('bytes must be base64 text');
  }
  if (bytes.length > mosaicMaxSaveBytes) {
    return refused('the file is larger than $mosaicMaxSaveBytes bytes');
  }
  // When the app says what it is saving, the name must agree: a JSON export
  // cannot be offered as `notes.exe`. Compared as Compose compares it (lower
  // case, no upper-case fold): the fold is for catching launchers, not for
  // widening what matches a type.
  final extensions = mosaicExtensionsFor(payload);
  final lowered = suggestedName.toLowerCase();
  if (extensions.isNotEmpty &&
      !extensions.any((extension) => lowered.endsWith('.$extension'))) {
    return refused(
      'suggestedName must end in an extension of an accepted type',
    );
  }
  if (extensions.isEmpty && mosaicHasExecutableExtension(suggestedName)) {
    return refused(
      'suggestedName must not end in an executable extension',
    );
  }
  return _MosaicSaveChecked((
    name: suggestedName,
    bytes: bytes,
    extensions: extensions,
  ));
}

/// [mosaicWriteReplacing] in a short-lived isolate; see
/// [_mosaicReadInBackground] for why this is a top-level function.
Future<Map<String, Object?>> _mosaicWriteInBackground(
  String target,
  Uint8List bytes,
) => Isolate.run(() => mosaicWriteReplacing(target, bytes));

/// Write [bytes] where the person chose and return the `files.save` outcome.
/// Never throws.
///
/// Written beside the target first and moved into place in one step, so an
/// interrupted save never leaves a half-written file where the person's old
/// one was. The temporary is created exclusively and written, flushed and
/// given its mode through the handle that created it -- never reopened by
/// path -- so nothing planted at its name (a link to `~/.bashrc`, say) is
/// ever followed, truncated or chmodded.
///
/// Synchronous: the router runs it in a background isolate.
/// [temporaryName] is for the conformance harness, which plants a link at a
/// known name; an app never passes it.
Map<String, Object?> mosaicWriteReplacing(
  String target,
  Uint8List bytes, {
  String? temporaryName,
}) {
  try {
    final full = File(target).absolute.path;
    final name = _mosaicBaseName(full);
    if (name.isEmpty) return mosaicFailed("couldn't save the file");
    final directory = File(full).parent.path;
    final temporary = temporaryName ?? _mosaicTemporaryName();
    final bool saved;
    if (Platform.isWindows) {
      saved = _mosaicSaveWindows(full, '$directory\\$temporary', bytes);
    } else {
      // A POSIX ABI without a flag table below cannot open safely: refuse.
      final posix = _MosaicPosix.load();
      saved =
          posix != null &&
          _mosaicSavePosix(posix, full, '$directory/$temporary', bytes);
    }
    return saved
        ? _mosaicOk(<String, Object?>{'name': name})
        : mosaicFailed("couldn't save the file");
  } on Object {
    return mosaicFailed("couldn't save the file");
  }
}

/// A name nobody else will pick: `.mosaic-save-<32 hex>.tmp`.
String _mosaicTemporaryName() {
  final random = Random.secure();
  final hex = StringBuffer();
  for (var index = 0; index < 16; index += 1) {
    hex.write(random.nextInt(256).toRadixString(16).padLeft(2, '0'));
  }
  return '.mosaic-save-$hex.tmp';
}

/// True when a `st_mode` (type bits included) is a regular file: `S_ISREG`.
/// `S_IFMT` and `S_IFREG` are the same on Linux and Apple platforms.
bool mosaicIsRegularMode(int mode) => mode & 0xF000 == 0x8000;

/// The mode a saved file gets, from what the chosen path held (Qt parity):
///
///   nothing there, or not a regular file (a link, a directory) .. 0600
///   a regular file this user owns ............ its rwx bits (& 0777)
///   a regular file someone else owns ........ 0600
///   a regular file whose owner is unknown .... its rwx bits without
///                                              group/other write (& 0755)
///
/// Never setuid, setgid or sticky: only the low nine bits survive. The
/// owner is unknown only where the library has no `lstat` to call (a glibc
/// older than 2.28), and then the bits come from a stat that follows links;
/// clearing the write bits means a link swapped in there can at worst lend
/// read access, never let another user write the saved file.
int mosaicReplacementMode(({int mode, int? uid})? existing, int currentUid) {
  if (existing == null || !mosaicIsRegularMode(existing.mode)) return 0x180;
  final owner = existing.uid;
  if (owner == null) return existing.mode & 0x1ED; // 0755
  return owner == currentUid ? existing.mode & 0x1FF : 0x180;
}

/// The POSIX save (Linux, macOS), as the Qt and SwiftUI libraries do it:
///
///   1. the mode, from `lstat` of the chosen path ([mosaicReplacementMode]);
///   2. `open(temporary, flags, 0600)` on `.mosaic-save-<random>.tmp` beside
///      the target, flags `O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW |
///      O_CLOEXEC` -- a new file or nothing: a link or anything else already
///      at that name fails the open, and is left alone;
///   3. the bytes written through that descriptor, then `fchmod` (never a
///      chmod by path, which would follow a link swapped in) and `fsync`;
///   4. `close`, then `rename(2)` onto the chosen path -- one step on the same
///      file system. Only if something failed is the temporary `unlink`ed
///      (which removes a name, never follows it).
bool _mosaicSavePosix(
  _MosaicPosix posix,
  String full,
  String temporary,
  Uint8List bytes,
) {
  final mode = mosaicReplacementMode(
    posix.statusOfPath(full) ?? _mosaicStatusWithoutOwner(full),
    posix.getuid(),
  );
  final length = bytes.length;
  // Allocated and filled before the open, so nothing between the open and
  // the `finally` blocks below can throw and leak the descriptor or leave
  // the temporary behind.
  final buffer = malloc<Uint8>(max(length, 1));
  try {
    buffer.asTypedList(length).setAll(0, bytes);
    final flags = posix.flags;
    final descriptor = posix.open(
      temporary,
      flags.writeOnly |
          flags.create |
          flags.exclusive |
          flags.noFollow |
          flags.closeOnExec,
      0x180, // 0600
    );
    // Nothing was created: whatever is at that name is not ours to remove.
    if (descriptor < 0) return false;
    var renamed = false;
    try {
      var complete = false;
      try {
        var written = 0;
        while (written < length) {
          final step = posix.write(
            descriptor,
            buffer + written,
            length - written,
          );
          // A regular file does not return EINTR mid-write; -1 or 0 fails.
          if (step <= 0) break;
          written += step;
        }
        complete =
            written == length &&
            posix.fchmod(descriptor, mode) == 0 &&
            posix.fsync(descriptor) == 0;
      } finally {
        if (posix.close(descriptor) != 0) complete = false;
      }
      renamed = complete && posix.rename(temporary, full) == 0;
      return renamed;
    } finally {
      // The temporary is ours (O_EXCL created it); unlink removes the name,
      // never follows it.
      if (!renamed) posix.unlink(temporary);
    }
  } finally {
    malloc.free(buffer);
  }
}

/// The chosen path's type and rwx bits, owner unknown -- for a POSIX system
/// where [_MosaicPosix.statusOfPath] has nothing to call.
({int mode, int? uid})? _mosaicStatusWithoutOwner(String path) {
  if (FileSystemEntity.typeSync(path, followLinks: false) !=
      FileSystemEntityType.file) {
    return null;
  }
  return (mode: 0x8000 | (FileStat.statSync(path).mode & 0xFFF), uid: null);
}

// ── The POSIX calls ───────────────────────────────────────────────────────
//
// dart:io can neither create a file exclusively AND keep the handle it
// created (an exclusive `createSync` closes it, and `openSync` then reopens
// by path, following whatever is there by then -- `O_CREAT | O_TRUNC`, no
// `O_EXCL`, no `O_NOFOLLOW`), nor create with a mode, nor `fchmod`, nor open
// without blocking. So the save and the open go to libc through dart:ffi, as
// the Qt and SwiftUI libraries call it directly.

/// The `open(2)` flags this library passes, for one ABI, as that platform's
/// headers define them. They differ by OS and, for `O_NOFOLLOW`, by
/// architecture on Linux: a wrong value here would silently drop a
/// protection, so each table is pinned by a test and checked by the
/// conformance harness against the running kernel.
final class MosaicOpenFlags {
  const MosaicOpenFlags({
    required this.writeOnly,
    required this.create,
    required this.exclusive,
    required this.nonBlocking,
    required this.noFollow,
    required this.closeOnExec,
  });

  /// `O_RDONLY`: 0 everywhere.
  static const int readOnly = 0;

  final int writeOnly;
  final int create;
  final int exclusive;
  final int nonBlocking;
  final int noFollow;
  final int closeOnExec;
}

/// The flag table for [abi], or null where this library has none (it then
/// refuses to save, and opens through dart:io).
///
///   flag         Linux x64   Linux arm64   macOS (x64, arm64)
///   O_WRONLY     0x1         0x1           0x1
///   O_CREAT      0x40        0x40          0x200
///   O_EXCL       0x80        0x80          0x800
///   O_NONBLOCK   0x800       0x800         0x4
///   O_NOFOLLOW   0x20000     0x8000        0x100
///   O_CLOEXEC    0x80000     0x80000       0x1000000
///
/// (Linux: asm-generic/fcntl.h, with arch/arm64's own O_NOFOLLOW; Apple:
/// sys/fcntl.h.) These are the ABIs Flutter builds desktop apps for.
MosaicOpenFlags? mosaicOpenFlagsFor(Abi abi) => switch (abi) {
  Abi.linuxX64 => const MosaicOpenFlags(
    writeOnly: 0x1,
    create: 0x40,
    exclusive: 0x80,
    nonBlocking: 0x800,
    noFollow: 0x20000,
    closeOnExec: 0x80000,
  ),
  Abi.linuxArm64 => const MosaicOpenFlags(
    writeOnly: 0x1,
    create: 0x40,
    exclusive: 0x80,
    nonBlocking: 0x800,
    noFollow: 0x8000,
    closeOnExec: 0x80000,
  ),
  Abi.macosX64 || Abi.macosArm64 => const MosaicOpenFlags(
    writeOnly: 0x1,
    create: 0x200,
    exclusive: 0x800,
    nonBlocking: 0x4,
    noFollow: 0x100,
    closeOnExec: 0x1000000,
  ),
  _ => null,
};

typedef _MosaicOpenNative =
    Int32 Function(Pointer<Utf8>, Int32, VarArgs<(Uint32,)>);
typedef _MosaicOpen = int Function(Pointer<Utf8>, int, int);
typedef _MosaicTransferNative = IntPtr Function(Int32, Pointer<Uint8>, Size);
typedef _MosaicTransfer = int Function(int, Pointer<Uint8>, int);
typedef _MosaicDescriptorNative = Int32 Function(Int32);
typedef _MosaicDescriptor = int Function(int);
typedef _MosaicPathNative = Int32 Function(Pointer<Utf8>);
typedef _MosaicPath = int Function(Pointer<Utf8>);
typedef _MosaicTwoPathsNative = Int32 Function(Pointer<Utf8>, Pointer<Utf8>);
typedef _MosaicTwoPaths = int Function(Pointer<Utf8>, Pointer<Utf8>);
typedef _MosaicStatxNative =
    Int32 Function(Int32, Pointer<Utf8>, Int32, Uint32, Pointer<Uint8>);
typedef _MosaicStatx = int Function(int, Pointer<Utf8>, int, int, Pointer<Uint8>);
typedef _MosaicStatPathNative = Int32 Function(Pointer<Utf8>, Pointer<Uint8>);
typedef _MosaicStatPath = int Function(Pointer<Utf8>, Pointer<Uint8>);
typedef _MosaicStatDescriptorNative = Int32 Function(Int32, Pointer<Uint8>);
typedef _MosaicStatDescriptor = int Function(int, Pointer<Uint8>);

/// libc, for the calls dart:io does not make. [load] returns null on an ABI
/// without a flag table, or when a required symbol is missing.
///
/// `stat` layouts: on Linux, `statx` (glibc 2.28+), whose `struct statx` is
/// the same on every architecture -- stx_mask u32 @0, stx_uid u32 @20,
/// stx_mode u16 @28 -- where `struct stat` is not. On Apple platforms the
/// 64-bit-inode `struct stat` -- st_mode u16 @4, st_uid u32 @16 -- which
/// arm64 exports as `lstat`/`fstat` and x86_64 as `lstat$INODE64`/
/// `fstat$INODE64` (its plain `lstat` is the old 32-bit-inode layout).
final class _MosaicPosix {
  _MosaicPosix._(this.flags, DynamicLibrary libc)
    : _open = libc.lookupFunction<_MosaicOpenNative, _MosaicOpen>('open'),
      _read = libc.lookupFunction<_MosaicTransferNative, _MosaicTransfer>(
        'read',
      ),
      _write = libc.lookupFunction<_MosaicTransferNative, _MosaicTransfer>(
        'write',
      ),
      _fsync = libc.lookupFunction<_MosaicDescriptorNative, _MosaicDescriptor>(
        'fsync',
      ),
      _close = libc.lookupFunction<_MosaicDescriptorNative, _MosaicDescriptor>(
        'close',
      ),
      _rename = libc.lookupFunction<_MosaicTwoPathsNative, _MosaicTwoPaths>(
        'rename',
      ),
      _unlink = libc.lookupFunction<_MosaicPathNative, _MosaicPath>('unlink'),
      _getuid = libc.lookupFunction<Uint32 Function(), int Function()>(
        'getuid',
      ),
      // mode_t is 32 bits on Linux and 16 on Apple platforms.
      _fchmod = Platform.isLinux
          ? libc.lookupFunction<Int32 Function(Int32, Uint32), int Function(int, int)>(
              'fchmod',
            )
          : libc.lookupFunction<Int32 Function(Int32, Uint16), int Function(int, int)>(
              'fchmod',
            ),
      _statx = Platform.isLinux && libc.providesSymbol('statx')
          ? libc.lookupFunction<_MosaicStatxNative, _MosaicStatx>('statx')
          : null,
      _lstat = Platform.isMacOS && libc.providesSymbol(_appleStat('lstat'))
          ? libc.lookupFunction<_MosaicStatPathNative, _MosaicStatPath>(
              _appleStat('lstat'),
            )
          : null,
      _fstat = Platform.isMacOS && libc.providesSymbol(_appleStat('fstat'))
          ? libc.lookupFunction<_MosaicStatDescriptorNative, _MosaicStatDescriptor>(
              _appleStat('fstat'),
            )
          : null;

  /// The 64-bit-inode `stat` family's symbol on this Apple ABI.
  static String _appleStat(String name) =>
      Abi.current() == Abi.macosX64 ? '$name\$INODE64' : name;

  static _MosaicPosix? load() {
    final flags = mosaicOpenFlagsFor(Abi.current());
    if (flags == null) return null;
    try {
      return _MosaicPosix._(flags, DynamicLibrary.process());
    } on Object {
      return null;
    }
  }

  final MosaicOpenFlags flags;
  final _MosaicOpen _open;
  final _MosaicTransfer _read;
  final _MosaicTransfer _write;
  final _MosaicDescriptor _fsync;
  final _MosaicDescriptor _close;
  final _MosaicTwoPaths _rename;
  final _MosaicPath _unlink;
  final int Function() _getuid;
  final int Function(int, int) _fchmod;
  final _MosaicStatx? _statx;
  final _MosaicStatPath? _lstat;
  final _MosaicStatDescriptor? _fstat;

  static const int _atFdCwd = -100;
  static const int _atSymlinkNoFollow = 0x100;
  static const int _atEmptyPath = 0x1000;
  static const int _statxTypeModeUid = 0x1 | 0x2 | 0x8; // TYPE | MODE | UID

  int open(String path, int flags, int mode) =>
      _withPath(path, (native) => _open(native, flags, mode));
  int read(int descriptor, Pointer<Uint8> buffer, int length) =>
      _read(descriptor, buffer, length);
  int write(int descriptor, Pointer<Uint8> buffer, int length) =>
      _write(descriptor, buffer, length);
  int fchmod(int descriptor, int mode) => _fchmod(descriptor, mode);
  int fsync(int descriptor) => _fsync(descriptor);
  int close(int descriptor) => _close(descriptor);
  int unlink(String path) => _withPath(path, _unlink);
  int getuid() => _getuid();
  int rename(String from, String to) => _withPath(
    from,
    (source) => _withPath(to, (destination) => _rename(source, destination)),
  );

  /// `lstat(path)`: its type and mode bits and its owner, without following
  /// a link; null when there is nothing there or nothing to call.
  ({int mode, int? uid})? statusOfPath(String path) {
    final statx = _statx;
    final lstat = _lstat;
    if (statx == null && lstat == null) return null;
    return _withPath(
      path,
      (native) => _status(
        (buffer) => statx != null
            ? statx(_atFdCwd, native, _atSymlinkNoFollow, _statxTypeModeUid, buffer)
            : lstat!(native, buffer),
      ),
    );
  }

  /// `fstat(descriptor)`; null when there is nothing to call.
  ({int mode, int? uid})? statusOfDescriptor(int descriptor) {
    final statx = _statx;
    final fstat = _fstat;
    if (statx == null && fstat == null) return null;
    return _withPath(
      '',
      (empty) => _status(
        (buffer) => statx != null
            ? statx(descriptor, empty, _atEmptyPath, _statxTypeModeUid, buffer)
            : fstat!(descriptor, buffer),
      ),
    );
  }

  ({int mode, int? uid})? _status(int Function(Pointer<Uint8>) call) {
    const size = 512; // struct statx is 256 bytes, Apple's struct stat 144
    final buffer = calloc<Uint8>(size);
    try {
      if (call(buffer) != 0) return null;
      final view = ByteData.sublistView(buffer.asTypedList(size));
      if (_statx != null) {
        final mask = view.getUint32(0, Endian.host);
        if (mask & _statxTypeModeUid != _statxTypeModeUid) return null;
        return (
          mode: view.getUint16(28, Endian.host),
          uid: view.getUint32(20, Endian.host),
        );
      }
      return (
        mode: view.getUint16(4, Endian.host),
        uid: view.getUint32(16, Endian.host),
      );
    } finally {
      calloc.free(buffer);
    }
  }

  static T _withPath<T>(String path, T Function(Pointer<Utf8>) call) {
    final native = path.toNativeUtf8();
    try {
      return call(native);
    } finally {
      malloc.free(native);
    }
  }
}

// ── The Windows save ──────────────────────────────────────────────────────

typedef _MosaicCreateFileNative =
    Pointer<Void> Function(
      Pointer<Utf16>,
      Uint32,
      Uint32,
      Pointer<Void>,
      Uint32,
      Uint32,
      Pointer<Void>,
    );
typedef _MosaicCreateFile =
    Pointer<Void> Function(
      Pointer<Utf16>,
      int,
      int,
      Pointer<Void>,
      int,
      int,
      Pointer<Void>,
    );
typedef _MosaicWriteFileNative =
    Int32 Function(
      Pointer<Void>,
      Pointer<Uint8>,
      Uint32,
      Pointer<Uint32>,
      Pointer<Void>,
    );
typedef _MosaicWriteFile =
    int Function(Pointer<Void>, Pointer<Uint8>, int, Pointer<Uint32>, Pointer<Void>);
typedef _MosaicHandleNative = Int32 Function(Pointer<Void>);
typedef _MosaicHandle = int Function(Pointer<Void>);
typedef _MosaicWidePathNative = Int32 Function(Pointer<Utf16>);
typedef _MosaicWidePath = int Function(Pointer<Utf16>);
typedef _MosaicMoveFileExNative =
    Int32 Function(Pointer<Utf16>, Pointer<Utf16>, Uint32);
typedef _MosaicMoveFileEx = int Function(Pointer<Utf16>, Pointer<Utf16>, int);

/// The Windows save, through the handle that created the temporary:
///
///   1. `CreateFileW(temporary, GENERIC_WRITE, no sharing, CREATE_NEW,
///      FILE_FLAG_OPEN_REPARSE_POINT)` -- a new file or nothing: anything
///      already at that name, a link included, fails the call and is left
///      alone (the reparse-point flag is belt and braces);
///   2. `WriteFile` and `FlushFileBuffers` on that handle, then `CloseHandle`;
///   3. `MoveFileExW(MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH)` --
///      the move the generated host uses for its own state file. Only if
///      something failed is the temporary deleted (`DeleteFileW` removes a
///      link, never what it points at).
///
/// A new file inherits the folder's ACL, and so does a replaced one, as with
/// the Compose and Qt libraries (XAML's `File.Replace` keeps the old file's
/// ACL; that is recorded as the difference, UI87 §7.7).
bool _mosaicSaveWindows(String full, String temporary, Uint8List bytes) {
  final kernel32 = DynamicLibrary.open('kernel32.dll');
  final createFile = kernel32
      .lookupFunction<_MosaicCreateFileNative, _MosaicCreateFile>('CreateFileW');
  final writeFile = kernel32
      .lookupFunction<_MosaicWriteFileNative, _MosaicWriteFile>('WriteFile');
  final flushFileBuffers = kernel32
      .lookupFunction<_MosaicHandleNative, _MosaicHandle>('FlushFileBuffers');
  final closeHandle = kernel32
      .lookupFunction<_MosaicHandleNative, _MosaicHandle>('CloseHandle');
  final deleteFile = kernel32
      .lookupFunction<_MosaicWidePathNative, _MosaicWidePath>('DeleteFileW');
  final moveFileEx = kernel32
      .lookupFunction<_MosaicMoveFileExNative, _MosaicMoveFileEx>('MoveFileExW');
  const genericWrite = 0x40000000;
  const createNew = 1;
  const fileAttributeNormal = 0x80;
  // Belt and braces with CREATE_NEW: never act on a reparse point's target.
  const fileFlagOpenReparsePoint = 0x00200000;
  const invalidHandleValue = -1; // (HANDLE)-1
  const moveFileReplaceExisting = 0x1;
  const moveFileWriteThrough = 0x8;

  final source = temporary.toNativeUtf16();
  final destination = full.toNativeUtf16();
  final length = bytes.length;
  final buffer = malloc<Uint8>(max(length, 1));
  final count = calloc<Uint32>();
  try {
    buffer.asTypedList(length).setAll(0, bytes);
    final handle = createFile(
      source,
      genericWrite,
      0,
      nullptr,
      createNew,
      fileAttributeNormal | fileFlagOpenReparsePoint,
      nullptr,
    );
    if (handle.address == invalidHandleValue) return false;
    var complete = false;
    try {
      var written = 0;
      while (written < length) {
        final ok = writeFile(
          handle,
          buffer + written,
          length - written,
          count,
          nullptr,
        );
        if (ok == 0 || count.value == 0) break;
        written += count.value;
      }
      complete = written == length && flushFileBuffers(handle) != 0;
    } finally {
      if (closeHandle(handle) == 0) complete = false;
    }
    if (complete &&
        moveFileEx(
              source,
              destination,
              moveFileReplaceExisting | moveFileWriteThrough,
            ) !=
            0) {
      return true;
    }
    deleteFile(source);
    return false;
  } finally {
    calloc.free(count);
    malloc.free(buffer);
    malloc.free(destination);
    malloc.free(source);
  }
}

// ── Phones: the document plugin (UI89 §7.11) ─────────────────────────────
//
// On Android and iOS there are no file dialogs to return a path the library
// reads and writes in place. A phone build's plugin, `mosaic_phone_files`,
// shows the system's pickers instead and moves the bytes between the
// person's document and a private file:
//
//     files.open                              files.save
//     ----------                              ----------
//     request directory (fresh)               the request checked, as on desktop
//     plugin: picker -> bounded copy          request directory (fresh)
//       into <directory>/<name>               staged as <directory>/<suggestedName>
//     the copy checked: a regular file,       plugin: export picker -> the
//       directly in <directory>, no link        provider's copy of the staged file
//     read with the desktop's bounded read    answer: ok { the reported name }
//     answer: ok { name, mimeType, bytes }
//                    the request directory removed, whatever happened
//
// The plugin is an interface here, so the conformance harness answers it
// with fakes on the plain Dart VM; `mosaic_platform_effects.dart` adapts the
// real `MethodChannel`. Paths cross the channel, never bytes: the bounded
// read and the save's checks stay in this file, shared with the desktop.

/// The name of the directory, under the app's temporary directory, that holds
/// each request's private directory.
const String mosaicPhoneFilesDirectoryName = 'mosaic-files';

/// How long a request directory must have gone unchanged before a later
/// process may delete it as a leftover of one that was killed.
const Duration mosaicPhoneLeftoverAge = Duration(hours: 1);

/// A failure the plugin reported, by its code: `busy`, `no_window`,
/// `activity_gone`, `too_large`, `stalled` or `unreadable`. The app is told a
/// fixed message for the code, never the platform's own text, which can carry
/// a provider's path.
final class MosaicPhoneDocumentsException implements Exception {
  const MosaicPhoneDocumentsException(this.code);

  final String code;

  @override
  String toString() => 'MosaicPhoneDocumentsException($code)';
}

/// The phone build's document plugin. Each method answers null for a cancel
/// and throws a [MosaicPhoneDocumentsException] for a failure it can name;
/// anything else it throws is the generic failure.
abstract interface class MosaicPhoneDocuments {
  /// The app's temporary directory: `cacheDir` on Android, the sandbox's
  /// `tmp/` on iOS. Request directories are made below it.
  Future<String> temporaryDirectory();

  /// Show the open picker for [mimeTypes] (any document when empty) and copy
  /// the chosen document, at most [limit] bytes, into a new file directly in
  /// [directory]. Returns that file's path.
  Future<String?> copyForOpening(
    String directory,
    List<String> mimeTypes,
    int limit,
  );

  /// Show the export picker for the file at [stagedPath], typed [mimeType].
  /// Returns the name the picker or provider reports for the saved document.
  Future<String?> export(String stagedPath, String mimeType);
}

/// The fixed message for a plugin failure. [saving] picks the save's wording;
/// an unknown code, or anything that is not a [MosaicPhoneDocumentsException]
/// (a missing plugin, an answer of the wrong shape), is the generic one.
String mosaicPhoneFailureMessage(Object error, {required bool saving}) {
  final code = error is MosaicPhoneDocumentsException ? error.code : null;
  return switch (code) {
    'busy' => 'another file operation is in progress',
    'no_window' => 'there is no window to show the file picker in',
    'activity_gone' => 'the file picker closed with the app',
    'too_large' when saving =>
      'the file is larger than $mosaicMaxSaveBytes bytes',
    'too_large' => 'the selected file is larger than $mosaicMaxOpenBytes bytes',
    'stalled' when saving => 'the file stopped saving',
    'stalled' => 'the selected file stopped arriving',
    _ when saving => "couldn't save the file",
    _ => "couldn't read the selected file",
  };
}

/// The characters that reorder text (UI89 §3.8): ARABIC LETTER MARK,
/// LEFT-TO-RIGHT and RIGHT-TO-LEFT MARK, the embeddings and overrides, and
/// the isolates.
bool _mosaicIsBidiControl(int unit) =>
    unit == 0x061C ||
    unit == 0x200E ||
    unit == 0x200F ||
    (unit >= 0x202A && unit <= 0x202E) ||
    (unit >= 0x2066 && unit <= 0x2069);

/// A name a picker or provider reported, as the app may be told it: the part
/// after any `/` or `\`, when that is an ordinary name, else `document`
/// (UI89 §3.8, with §7.11's byte clause).
///
///     reported                    told
///     notes.json                  notes.json
///     /storage/x/notes.json       notes.json
///     ""  "."  ".."  "   "         document
///     evil<U+202E>gnp.exe     document   (a bidi override disguises it)
///     a\nb                        document   (a control character)
///     300 x "é" (600 bytes)     document   (over 255 UTF-8 bytes)
///
/// Other format characters -- the zero-width joiners of Persian, Devanagari
/// and emoji sequences, a soft hyphen -- are ordinary writing and pass, as on
/// Android.
String mosaicOrdinaryReportedName(String reported) {
  final slash = reported.lastIndexOf('/');
  final backslash = reported.lastIndexOf(r'\');
  final name = reported.substring(max(slash, backslash) + 1);
  if (name.trim().isEmpty || name == '.' || name == '..') return 'document';
  if (name.length > 255 || utf8.encode(name).length > 255) return 'document';
  final units = name.codeUnits;
  for (var index = 0; index < units.length; index += 1) {
    final unit = units[index];
    // Paired surrogates are one ordinary character; a lone one is not.
    if (unit >= 0xD800 && unit <= 0xDBFF) {
      final next = index + 1 < units.length ? units[index + 1] : 0;
      if (next < 0xDC00 || next > 0xDFFF) return 'document';
      index += 1;
      continue;
    }
    if (unit >= 0xDC00 && unit <= 0xDFFF) return 'document';
    final control = unit < 0x20 || (unit >= 0x7F && unit <= 0x9F);
    final separator = unit == 0x2028 || unit == 0x2029;
    if (control || separator || _mosaicIsBidiControl(unit)) return 'document';
  }
  return name;
}

/// The MIME types the request accepts that the table knows, in order and
/// without repeats: what the open picker filters on. Empty is any document.
List<String> mosaicKnownMimeTypesFor(Object? payload) {
  final accept = payload is Map ? payload['accept'] : null;
  final known = <String>[];
  if (accept is! List) return known;
  for (final mime in accept) {
    if (mime is! String || known.contains(mime)) continue;
    if (_mosaicMimeExtensions.any((row) => row.$1 == mime)) known.add(mime);
  }
  return known;
}

/// The type a save asks the picker for (UI89 §3.8): the name's own type when
/// the request accepts it, or accepts anything; else the first type it
/// accepts.
String _mosaicSaveMimeType(String name, List<String> mimeTypes) {
  final own = _mosaicMimeTypeFor(name);
  if (mimeTypes.isEmpty || mimeTypes.contains(own)) return own;
  return mimeTypes.first;
}

/// Delete the request directories under [root] that have not changed for
/// [mosaicPhoneLeftoverAge] (a process killed mid-request leaves its own
/// behind). Nothing is followed through a link, and a link itself, whose age
/// cannot be read without following it, is left alone. Never throws.
///
/// Only old entries go: another Flutter engine in this process (an iPad's
/// second scene) has its own router, and may have a request in flight here.
void mosaicSweepPhoneLeftovers(Directory root, DateTime now) {
  final List<FileSystemEntity> entries;
  try {
    entries = root.listSync(followLinks: false);
  } on Object {
    return;
  }
  for (final entry in entries) {
    try {
      final type = FileSystemEntity.typeSync(entry.path, followLinks: false);
      if (type == FileSystemEntityType.link) continue;
      final changed = entry.statSync().modified;
      if (now.difference(changed) <= mosaicPhoneLeftoverAge) continue;
      // A recursive delete removes links inside, never what they point at.
      entry.deleteSync(recursive: true);
    } on Object {
      // Gone already, or not ours to delete: the next sweep tries again.
    }
  }
}

/// A fresh, empty directory for one request, under
/// `<temporary>/mosaic-files/`. [sweep] first removes old leftovers there.
///
/// The parent is the app's own temporary directory, which no other app can
/// reach on either phone, so the request directory is private to the app.
Future<Directory> _mosaicPhoneRequestDirectory(
  MosaicPhoneDocuments documents, {
  required bool sweep,
}) async {
  // Without a trailing separator (iOS's NSTemporaryDirectory() has one), so
  // the request path is the plain form a plugin answers within.
  var temporary = await documents.temporaryDirectory();
  while (temporary.length > 1 && temporary.endsWith('/')) {
    temporary = temporary.substring(0, temporary.length - 1);
  }
  final root = Directory('$temporary/$mosaicPhoneFilesDirectoryName');
  final type = FileSystemEntity.typeSync(root.path, followLinks: false);
  if (type == FileSystemEntityType.notFound) {
    try {
      root.createSync();
    } on FileSystemException {
      // Made by another engine between the check and the create.
    }
  }
  if (FileSystemEntity.typeSync(root.path, followLinks: false) !=
      FileSystemEntityType.directory) {
    throw StateError('the file request directory is not a directory');
  }
  if (sweep) mosaicSweepPhoneLeftovers(root, DateTime.now());
  return root.createTempSync('request-');
}

/// Whether [path], as the plugin answered it, is a regular file -- not a
/// link -- directly inside [directory]. The plugin is not trusted to have
/// written where it was told.
bool mosaicIsCopyInside(String path, String directory) {
  final name = _mosaicBaseName(path);
  if (name.isEmpty || name == '.' || name == '..') return false;
  if (path != '$directory/$name') return false;
  return FileSystemEntity.typeSync(path, followLinks: false) ==
      FileSystemEntityType.file;
}

/// [outcome] with its name made ordinary, and its type read again from that
/// name. The copy's name is the one the plugin chose, from a provider's
/// display name, so it is checked as a reported save name is.
Map<String, Object?> _mosaicWithOrdinaryName(Map<String, Object?> outcome) {
  if (!outcome.containsKey('ok')) return outcome; // failed or cancelled
  final opened = outcome['ok'];
  // Never an unchecked name: an answer of any other shape fails closed.
  if (opened is! Map<String, Object?>) return _mosaicUnreadable();
  final name = mosaicOrdinaryReportedName(opened['name'] as String? ?? '');
  return _mosaicOk(<String, Object?>{
    ...opened,
    'name': name,
    'mimeType': _mosaicMimeTypeFor(name),
  });
}

void _mosaicRemoveQuietly(Directory? directory) {
  try {
    directory?.deleteSync(recursive: true);
  } on Object {
    // Left for a later sweep.
  }
}

/// `files.open` on a phone: the outcome map, never an exception.
///
/// [sweep] removes old leftovers before the request directory is made; the
/// router asks for it on its first request only.
Future<Map<String, Object?>> mosaicRunPhoneFilesOpen(
  Object? payload,
  MosaicPhoneDocuments documents, {
  bool sweep = false,
}) async {
  Directory? request;
  try {
    request = await _mosaicPhoneRequestDirectory(documents, sweep: sweep);
    final String? copied;
    try {
      copied = await documents.copyForOpening(
        request.path,
        mosaicKnownMimeTypesFor(payload),
        mosaicMaxOpenBytes,
      );
    } on Object catch (error) {
      return mosaicFailed(mosaicPhoneFailureMessage(error, saving: false));
    }
    if (copied == null) return _mosaicCancelled();
    if (!mosaicIsCopyInside(copied, request.path)) return _mosaicUnreadable();
    // The desktop's bounded read: at most 50 MiB, whatever the plugin copied.
    final outcome = await _mosaicReadInBackground(copied);
    return _mosaicWithOrdinaryName(outcome);
  } on Object {
    return _mosaicUnreadable();
  } finally {
    _mosaicRemoveQuietly(request);
  }
}

/// `files.save` on a phone: the outcome map, never an exception.
///
/// The request is checked exactly as on desktop before anything is shown. The
/// bytes are staged under the suggested name, created exclusively in the
/// request's own directory, and the export picker hands that file to the
/// person, who chooses where it goes; the picker (iOS) or provider (Android)
/// confirms any replace. The answer's name is the one it reports, made
/// ordinary.
Future<Map<String, Object?>> mosaicRunPhoneFilesSave(
  Object? payload,
  MosaicPhoneDocuments documents, {
  bool sweep = false,
}) async {
  final checked = _mosaicCheckSaveRequest(payload);
  if (checked case _MosaicSaveRefused(:final outcome)) return outcome;
  final (:name, :bytes, :extensions) = (checked as _MosaicSaveChecked).request;
  Directory? request;
  try {
    request = await _mosaicPhoneRequestDirectory(documents, sweep: sweep);
    final staged = '${request.path}/$name';
    if (!await _mosaicStageInBackground(staged, bytes)) {
      return mosaicFailed("couldn't save the file");
    }
    final String? reported;
    try {
      reported = await documents.export(
        staged,
        _mosaicSaveMimeType(name, mosaicKnownMimeTypesFor(payload)),
      );
    } on Object catch (error) {
      return mosaicFailed(mosaicPhoneFailureMessage(error, saving: true));
    }
    if (reported == null) return _mosaicCancelled();
    return _mosaicOk(<String, Object?>{
      'name': mosaicOrdinaryReportedName(reported),
    });
  } on Object {
    return mosaicFailed("couldn't save the file");
  } finally {
    _mosaicRemoveQuietly(request);
  }
}

/// Write [bytes] to a new file at [staged], in a short-lived isolate. The
/// create is exclusive, so nothing already at that name is written through.
/// False when it could not be written.
Future<bool> _mosaicStageInBackground(String staged, Uint8List bytes) =>
    Isolate.run(() {
      RandomAccessFile? handle;
      try {
        final file = File(staged)..createSync(exclusive: true);
        handle = file.openSync(mode: FileMode.writeOnly);
        handle.writeFromSync(bytes);
        handle.flushSync();
        return true;
      } on Object {
        return false;
      } finally {
        try {
          handle?.closeSync();
        } on Object {
          // The write already failed or succeeded; closing changes neither.
        }
      }
    });

// ── Routing and installation ──────────────────────────────────────────────

/// Route one effect (UI87 §7.2). True when this library takes it, false when
/// it belongs to the app's handler, and null when nobody should answer it
/// here (the host then fails an unanswered Await).
bool? mosaicRoutesToPlatform(String kind, Set<String>? appKinds) {
  if (appKinds != null && appKinds.contains(kind)) return false;
  if (mosaicStandardEffectKinds.contains(kind)) return true;
  if (appKinds == null) return false;
  return null;
}

/// The routers installed, keyed by the handler each one set, so a second
/// install recognises the first instead of wrapping it. An `Expando` rather
/// than a field on the host: the host is the generated `MosaicHost`, which
/// knows nothing of this library.
final Expando<MosaicPlatformRouter> _mosaicRouters =
    Expando<MosaicPlatformRouter>('MosaicPlatformRouter');

/// The handler this library installs: it routes each effect by kind (UI87
/// §7.2) and answers the standard kinds itself.
final class MosaicPlatformRouter {
  MosaicPlatformRouter._(
    this._host,
    this._appHandler,
    this._appKinds,
    this._dialogs,
    this._phoneDocuments,
    this._hasDialogs,
    this._runOnUi,
  );

  final MosaicPlatformEffectHost _host;
  final MosaicEffectHandler? _appHandler;
  final Set<String>? _appKinds;
  final MosaicFileDialogs _dialogs;

  /// A phone build's document plugin (UI89 §7.11). When it is given, the
  /// standard kinds go through it rather than through [_dialogs].
  final MosaicPhoneDocuments? _phoneDocuments;
  final bool _hasDialogs;
  final void Function(void Function() work) _runOnUi;

  /// One file operation at a time (UI87 §3.1): a second request while a
  /// dialog is open is failed, not queued behind it. A plain bool: the
  /// isolate is single-threaded.
  bool _busy = false;

  /// Whether this router has swept old request directories on a phone: once,
  /// before its first request.
  bool _swept = false;

  void handle(int id, String kind, Object? payload, String delivery) {
    switch (mosaicRoutesToPlatform(kind, _appKinds)) {
      case false:
        // The app's, delivered as it was before the router existed. An
        // exception from it reaches the host's own catch, which fails the
        // effect with the reason -- exactly as it did then.
        _appHandler?.call(id, kind, payload, delivery);
      case null:
        return; // nobody: the host fails an unanswered Await
      case true:
        _answerStandard(id, kind, payload, delivery);
    }
  }

  void _answerStandard(int id, String kind, Object? payload, String delivery) {
    // Only an Await has someone waiting for the answer.
    if (delivery.toLowerCase() != 'await') return;
    // No dialogs here (Android, iOS): answer inline, which the host allows
    // inside its settle, instead of pretending the person cancelled.
    if (!_hasDialogs) {
      _host.completeEffect(
        id,
        mosaicFailed('$kind is not available on this platform yet'),
      );
      return;
    }
    // Copied BEFORE the router is marked busy: anything that can throw
    // between taking `_busy` and handing it to `_answer` must release it, and
    // the fewer such steps the better. (A throw here reaches the host's own
    // catch, which fails the effect with the reason -- it is not deferred.)
    final request = _mosaicCopyJson(payload);
    if (_busy) {
      _host.completeEffect(
        id,
        mosaicFailed('another file operation is in progress'),
      );
      return;
    }
    _busy = true;
    // Ownership first. False means the runtime is not waiting on this id,
    // and the right move is to open no dialog at all.
    final bool owned;
    try {
      owned = _host.deferEffect(id);
    } on Object {
      _busy = false;
      rethrow;
    }
    if (!owned) {
      _busy = false;
      return;
    }
    try {
      // `_answer` catches everything it can meet, so the discarded future
      // never completes with an error.
      _runOnUi(() => unawaited(_answer(id, kind, request)));
    } on Object {
      // The scheduler refused the work. Deferred, so the host will not fail
      // it: this is the last chance to answer.
      _busy = false;
      _tryComplete(id, mosaicFailed('the file dialog failed'));
    }
  }

  Future<void> _answer(int id, String kind, Object? request) async {
    Map<String, Object?> outcome;
    try {
      final phone = _phoneDocuments;
      if (phone != null) {
        final sweep = !_swept;
        _swept = true;
        outcome = kind == 'files.open'
            ? await mosaicRunPhoneFilesOpen(request, phone, sweep: sweep)
            : await mosaicRunPhoneFilesSave(request, phone, sweep: sweep);
      } else {
        outcome = kind == 'files.open'
            ? await mosaicRunFilesOpen(request, _dialogs)
            : await mosaicRunFilesSave(request, _dialogs);
      }
    } on Object {
      // A dialog that threw (no display, a sandbox without the file-access
      // entitlement, a file with no local path) -- not its text, which can
      // carry a path.
      outcome = mosaicFailed('the file dialog failed');
    } finally {
      _busy = false;
    }
    _tryComplete(id, outcome);
  }

  void _tryComplete(int id, Map<String, Object?> outcome) {
    try {
      _host.completeEffect(id, outcome);
    } on Object {
      // The host was disposed while the dialog was open (a retried start, or
      // the window closing). Nothing is waiting any more.
    }
  }
}

/// Install the platform library on [host], wrapping whatever handler the app
/// installed. [appKinds] is the app's `[host_effects]` `kinds`, or null when
/// it declared none (the original meaning: it receives every non-standard
/// kind). [phoneDocuments] is a phone build's document plugin (UI89 §7.11):
/// given, it answers the standard kinds instead of [dialogs], and the
/// platform has pickers whatever [hasDialogs] says. [dialogs], [hasDialogs] and [runOnUi]
/// are replaceable for tests;
/// [runOnUi] runs the dialog work after the current settle, and a throw from
/// it counts as the work refused.
///
/// Idempotent: when the host's handler is already a router, the app did not
/// reinstall its own since, and nothing changes. A retried start disposes the
/// host and loads a new one, with no handler, so it gets a new router, as it
/// gets the app's handler again.
void installMosaicPlatformRouter(
  MosaicPlatformEffectHost host, {
  required Iterable<String>? appKinds,
  required MosaicFileDialogs dialogs,
  MosaicPhoneDocuments? phoneDocuments,
  bool? hasDialogs,
  void Function(void Function() work) runOnUi = scheduleMicrotask,
}) {
  final current = host.effectHandler;
  if (current != null && _mosaicRouters[current] != null) return;
  final router = MosaicPlatformRouter._(
    host,
    current,
    appKinds?.toSet(),
    dialogs,
    phoneDocuments,
    (hasDialogs ?? mosaicPlatformHasFileDialogs) || phoneDocuments != null,
    runOnUi,
  );
  final MosaicEffectHandler handler = router.handle;
  _mosaicRouters[handler] = router;
  host.effectHandler = handler;
}
